const analysis = $json;
const products = $input.all().map(i => i.json);

function scoreProduct(p) {
  let score = 0;

  // Skin tone match
  if (p.skin_tone === analysis.skin_tone || p.skin_tone === 'all') {
    score += 30;
  }

  // Undertone match
  if (p.undertone === analysis.undertone || p.undertone === 'all') {
    score += 30;
  }

  // Shade family match (for blush/lip)
  const shade = (p.shade_family || '').toLowerCase();

  if (
    analysis.blush?.recommended_families?.some(f =>
      shade.includes(f.toLowerCase())
    )
  ) {
    score += 20;
  }

  if (
    analysis.lip?.everyday_families?.some(f =>
      shade.includes(f.toLowerCase())
    )
  ) {
    score += 20;
  }

  // Finish match
  if (
    p.finish &&
    p.finish === analysis.foundation?.finish
  ) {
    score += 10;
  }

  return score;
}

const ranked = products
  .map(p => ({
    ...p,
    score: scoreProduct(p)
  }))
  .sort((a, b) => b.score - a.score);

const topProducts = ranked.slice(0, 5);

return [{
  json: {
    ...analysis,
    recommendations: topProducts
  }
}];

const messageOutput = ($json.output || []).find(
  item => item.type === 'message' && item.content?.length
);

const text =
  messageOutput?.content?.find(c => c.type === 'output_text')?.text ||
  $json.output_text;

if (!text) {
  throw new Error('No analysis text found from OpenAI');
}

const cleaned = text
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(cleaned);

return [
  {
    json: {
      ...parsed
    }
  }
];

const a = $json;

const prompt = `
Create a premium, dermatology-grade makeup analysis infographic using the provided portrait.

STRICT REQUIREMENTS:
- Preserve exact facial identity, proportions, and skin texture.
- No beautification.
- No face alteration.
- Maintain realistic lighting and natural skin details.
- Use the SAME face consistently across all sections and variations.

LAYOUT:
- Center: High-resolution portrait with neutral clinical lighting.
- Surrounding: Structured UI cards in a clean grid layout.
- No clutter.
- No overlapping elements.

STYLE:
- Luxury dermatology + editorial beauty aesthetic.
- Color palette: soft beige, ivory, muted rose, charcoal accents.
- Typography: clean, modern, minimal.
- UI: rounded cards, subtle shadows, thin dividers.

CONTENT SECTIONS:

1. SKIN & FEATURE SUMMARY
- Skin tone: ${a.skin_tone}
- Undertone: ${a.undertone}
- Face shape: ${a.face_shape}
- Eye shape: ${a.eye_shape}
- Brow type: ${a.brow_type}

2. FOUNDATION MATCH
- Recommended undertones: ${(a.foundation?.recommended_undertones || []).join(', ')}
- Finish: ${a.foundation?.finish}
- Coverage: ${a.foundation?.coverage}

3. BLUSH RECOMMENDATIONS
- Shades: ${(a.blush?.recommended_families || []).join(', ')}
- Placement: ${a.blush?.placement}

4. LIP COLORS
- Everyday: ${(a.lip?.everyday_families || []).join(', ')}
- Glam: ${(a.lip?.glam_families || []).join(', ')}
- Finish: ${(a.lip?.finish_types || []).join(', ')}

5. BROW STYLING
- Shape: ${a.brow_type}
- Finish: Natural / Defined / Feathered

6. EYE MAKEUP LOOKS
- Everyday Soft: ${(a.eyes?.everyday_soft || []).join(', ')}
- Defined Classic: ${(a.eyes?.defined_classic || []).join(', ')}
- Evening Glam: ${(a.eyes?.evening_glam || []).join(', ')}

7. SCORES
Show score bars from 0 to 100:
- Skin Tone: ${a.confidence_scores?.skin_tone}
- Undertone: ${a.confidence_scores?.undertone}
- Foundation Match: ${a.confidence_scores?.foundation_match}
- Blush Match: ${a.confidence_scores?.blush_match}
- Lip Match: ${a.confidence_scores?.lip_match}
- Eye Makeup: ${a.confidence_scores?.eye_makeup}

VISUAL RULES:
- Use subtle annotation lines only where needed.
- No exaggerated effects.
- No cartoon styling.
- No stock icons.
- Short text only.
- High-resolution infographic poster.
- Balanced spacing, symmetrical layout.
- Clean, structured, premium finish.
`;

return [{
  json: {
    chat_id: a.chat_id,
    prompt,
    original_image_base64: a.original_image_base64
  }
}];

const originalBinary = $('Get a file').first().binary?.data;

if (!originalBinary) {
  throw new Error('No binary image found from Get a file node');
}

return [{
  json: {
    chat_id: $json.chat_id,
    prompt: $json.prompt
  },
  binary: {
    data: originalBinary
  }
}];

const b64 = $json.data?.[0]?.b64_json;

if (!b64) {
  throw new Error('No generated image found in OpenAI response');
}

return [{
  json: {
    chat_id: $('Build Infographic Prompt').first().json.chat_id
  },
  binary: {
    data: {
      data: b64,
      mimeType: 'image/png',
      fileName: 'makeup-infographic.png'
    }
  }
}];

const items = $input.all().map(i => i.json);

if (!items.length) {
  return [{
    json: {
      chat_id: $('Send a photo message').first().json.result.chat.id,
      message: `✨ Your makeup analysis is ready.\n\nWe could not find matching products right now. Please try again later.`
    }
  }];
}

const top = items
  .filter(p => String(p.Status || '').toLowerCase() === 'active')
  .sort((a, b) => Number(b.priority_score || 0) - Number(a.priority_score || 0))
  .slice(0, 5);

const grouped = {
  foundation: top.filter(p => p.match_category === 'foundation').slice(0, 1),
  blush: top.filter(p => p.match_category === 'blush').slice(0, 1),
  lip: top.filter(p => p.match_category === 'lip').slice(0, 2),
  eyes: top.filter(p => p.match_category === 'eyes').slice(0, 1),
  brow: top.filter(p => p.match_category === 'brow').slice(0, 1),
};

function line(p, label) {
  return `${label}\n${p.Title}\n₹${p['Variant Price']}\nWhy: ${p.match_undertone} undertone + ${p.match_shade_family}\nBuy: ${p['Product URL']}`;
}

let message = `✨ Your personalized makeup picks are ready\n\nBased on your makeup analysis, these products are the best fit from the brand catalogue:\n`;

if (grouped.foundation.length) {
  message += `\n\n🧴 FOUNDATION\n${line(grouped.foundation[0], 'Best base match')}`;
}

if (grouped.blush.length) {
  message += `\n\n🌸 BLUSH\n${line(grouped.blush[0], 'Best cheek color')}`;
}

if (grouped.lip.length) {
  message += `\n\n💄 LIPS\n${grouped.lip.map((p, i) => line(p, i === 0 ? 'Everyday pick' : 'Glam pick')).join('\n\n')}`;
}

if (grouped.eyes.length) {
  message += `\n\n👁️ EYES\n${line(grouped.eyes[0], 'Best eye look match')}`;
}

if (grouped.brow.length) {
  message += `\n\n🤎 BROWS\n${line(grouped.brow[0], 'Best brow product')}`;
}

message += `\n\nTap the links to view products. Shade matching is AI-assisted, so check shade swatches before purchase.`;

return [{
  json: {
    chat_id: $('Send a photo message').first().json.result.chat.id,
    message
  }
}];
